 "content": "def transform(grid):
    """Stamp the marked pattern onto every translated all-zero match."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    marks = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0, 1, 6)]
    if not marks:
        return g
    color = marks[0][2]
    rs = [r for r, c, v in marks]
    cs = [c for r, c, v in marks]
    r0, c0 = min(rs), min(cs)
    pattern = [(r-r0, c-c0) for r, c, v in marks]
    ph, pw = max(r for r, c in pattern)+1, max(c for r, c in pattern)+1
    for dr in range(h-ph+1):
        for dc in range(w-pw+1):
            if all(g[dr+r][dc+c] == 0 for r, c in pattern):
                for r, c in pattern:
                    g[dr+r][dc+c] = color
    return g
